"879 :     public int getOffsetFromLocal(long instantLocal) {
880 :         // get the offset at instantLocal (first estimate)
881 :         final int offsetLocal = getOffset(instantLocal);
882 :         // adjust instantLocal using the estimate and recalc the offset
883 :         final long instantAdjusted = instantLocal - offsetLocal;
884 :         final int offsetAdjusted = getOffset(instantAdjusted);
885 :         // if the offsets differ, we must be near a DST boundary
886 :         if (offsetLocal != offsetAdjusted) {
887 :             // we need to ensure that time is always after the DST gap
888 :             // this happens naturally for positive offsets, but not for negative
889 :             if ((offsetLocal - offsetAdjusted) < 0) {
890 :                 // if we just return offsetAdjusted then the time is pushed
891 :                 // back before the transition, whereas it should be
892 :                 // on or after the transition
893 :                 long nextLocal = nextTransition(instantAdjusted);
894 :                 long nextAdjusted = nextTransition(instantLocal - offsetAdjusted);
895 :                 if (nextLocal != nextAdjusted) {
896 :                     return offsetLocal;
897 :                 }
898 :             }
899 :         }
900 :         return offsetAdjusted;
901 :     }"

